  "summary": "The code contains a critical open redirect vulnerability, hardcoded port configuration, and lacks basic security hardening. Overall code health is poor due to these security and maintainability oversights.",
  "fixed_code": "const express = require('express');\nconst helmet = require('helmet');\n\nconst app = express();\napp.use(helmet());\n\n/**\n * Completes the login process by setting a welcome cookie and redirecting the user.\n * @param {string} [req.query.returnTo] - The URL to redirect to after login.\n */\napp.get('/login/complete', (req, res) => {\n    const allowed = ['/dashboard', '/profile'];\n    const target = allowed.includes(req.query.returnTo) ? req.query.returnTo : '/dashboard';\n    \n    res.cookie('seen_welcome', '1', { httpOnly: true, secure: true });\n    res.redirect(target);\n});\n\nconst PORT = process.env.PORT || 3000;\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
